function initProductSearchIndex() {
    if (typeof ALL_PRODUCTS === 'undefined' || !Array.isArray(ALL_PRODUCTS)) return;
    for (let i = 0; i < ALL_PRODUCTS.length; i++) {
        const p = ALL_PRODUCTS[i];
        if (!p._searchStr) {
            p._searchStr = ((p.urunAdi || '') + ' ' + (p.marka || '') + ' ' + (p.icerik || '') + ' ' + (p.endikasyon || '') + ' ' + (p.tags || '')).toLowerCase();
            p._titleLower = (p.urunAdi || '').toLowerCase();
            p._brandLower = (p.marka || '').toLowerCase();
        }
    }
}


function getPurityTier(product, queryTerm, aliases = []) {
    const title = (product.urunAdi || '').toLowerCase();
    const icerik = (product.icerik || '').toLowerCase();
    const tags = (product.tags || '').toLowerCase();
    const titleAndIcerik = title + ' ' + icerik;
    const q = (queryTerm || '').toLowerCase().trim();

    const terms = [q, ...aliases.map(a => a.toLowerCase())].filter(t => t.length >= 2);

    const titleOrTagsMatch = terms.some(t => {
        return new RegExp('\\b' + escapeRegex(t) + '\\b', 'i').test(title) ||
               title.includes(t) ||
               new RegExp('\\b' + escapeRegex(t) + '\\b', 'i').test(tags);
    });

    const isExplicitMulti = /\b(multi|multivitamin|multi-vitamin|all-in-one|prenatal|spectrum|blend|greens|pack|packet|herbal mix)\b/i.test(title) ||
                            /\b(multi|multivitamin|multi-vitamin)\b/i.test(tags);

    const searchedFamilyKeys = new Set();
    NUTRIENT_FAMILIES.forEach(f => {
        if (terms.some(t => f.pattern.test(t))) {
            searchedFamilyKeys.add(f.key);
        }
    });

    let otherNutrientCount = 0;
    NUTRIENT_FAMILIES.forEach(f => {
        if (!searchedFamilyKeys.has(f.key)) {
            if (f.pattern.test(titleAndIcerik)) {
                otherNutrientCount++;
            }
        }
    });

    // Tier 1: SAF / TEKİL (Aranan madde tek başına, yabancı vitamin/mineral yok)
    if (titleOrTagsMatch && !isExplicitMulti && otherNutrientCount === 0) {
        return 1;
    }

    // Tier 2: ODAKLI SİNERJİ (Hedefe yönelik 1-2 sinerjik kofaktör: örn Mg+P5P veya D3+K2)
    if (titleOrTagsMatch && !isExplicitMulti && otherNutrientCount <= 2) {
        return 2;
    }

    // Tier 3: KARIŞIK / KOMPLEKS / MULTİVİTAMİN (3+ diğer etken veya geniş multivitamin)
    return 3;
}

