function escapeHtml(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function escapeRegex(string) {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// VIEW MODE CONTROLLER (KLASİK TABLO VS MODERN KARTLAR)
function setViewMode(mode) {
    currentViewMode = mode;
    updateViewModeUI();
    const filtered = filterAndSortProducts();
    if (currentViewMode === 'table') {
        renderProductsTable(filtered, false);
    } else {
        renderProductsGrid(filtered, false);
    }
}

function updateViewModeUI() {
    const btnTable = document.getElementById('viewModeTableBtn');
    const btnGrid = document.getElementById('viewModeGridBtn');
    const tableContainer = document.getElementById('productsTableContainer');
    const gridContainer = document.getElementById('productsGrid');

    if (currentViewMode === 'table') {
        if (btnTable) btnTable.classList.add('active');
        if (btnGrid) btnGrid.classList.remove('active');
        if (tableContainer) tableContainer.style.display = 'block';
        if (gridContainer) gridContainer.style.display = 'none';
    } else {
        if (btnTable) btnTable.classList.remove('active');
        if (btnGrid) btnGrid.classList.add('active');
        if (tableContainer) tableContainer.style.display = 'none';
        if (gridContainer) gridContainer.style.display = 'grid';
    }
}

// CLINICAL MODULAR QUERY ROUTER
function getClinicalQueryIntent(query) {
    if (!query || !query.trim()) return null;
    const q = query.toLowerCase().trim();

    // 1. D Vitamini Ailesi
    if (/^(d\s*vitamini|vitamin\s*d|d-vitamini|d\s*vit|d3\s*vitamini|vitamin\s*d3|d3|d2|kolekalsiferol|cholecalciferol|ergokalsiferol)$/i.test(q) ||
        (q.includes('d vitamini') || q.includes('vitamin d') || q === 'd3' || q === 'd')) {
        return {
            family: 'D_VITAMIN',
            unitType: 'iu',
            filterRegex: /\b(d\s*vitamini|vitamin\s*d|d-vitamini|d3\b|d2\b|kolekalsiferol|cholecalciferol|ergokalsiferol|kalsidiol|calcifediol)\b/i,
            highlightTerms: [
                'd vitamini', 'd-vitamini', 'vitamin d', 'd3 vitamini', 'vitamin d3',
                'd3', 'd2', 'kolekalsiferol', 'cholecalciferol', 'ergokalsiferol'
            ],
            sortAliases: ['vitamin d3', 'd3 vitamini', 'd3', 'kolekalsiferol', 'vitamin d', 'd vitamini']
        };
    }

    // 2. B12 Vitamini (Özel Hassasiyet - B12 içermeyenler veya sadece emilim bahsedenler elenir)
    if (/^(b12|vitamin\s*b12|b12\s*vitamini|b-12|metilkobalamin|adenozilkobalamin|hidroksokobalamin|siyanokobalamin|kobalamin)$/i.test(q) ||
        q === 'b12' || q.includes('b12 vitamini') || q.includes('vitamin b12')) {
        return {
            family: 'B12_VITAMIN',
            unitType: 'mcg',
            filterRegex: /\b(b12\b|vitamin\s*b12|b12\s*vitamini|metilkobalamin|adenozilkobalamin|hidroksokobalamin|siyanokobalamin|kobalamin|mecobalactive)\b/i,
            highlightTerms: [
                'b12 vitamini', 'vitamin b12', 'b12', 'metilkobalamin', 'adenozilkobalamin',
                'hidroksokobalamin', 'siyanokobalamin', 'kobalamin', 'mecobalactive'
            ],
            sortAliases: ['b12', 'metilkobalamin', 'adenozilkobalamin', 'hidroksokobalamin', 'kobalamin']
        };
    }

    // 3. Genel B Vitamini Ailesi
    if (/^(b\s*vitamini|vitamin\s*b|b-vitamini|b\s*vit|b\s*kompleks|b-kompleks|b)$/i.test(q) ||
        (q.includes('b vitamini') || q.includes('vitamin b') || q.includes('b kompleks'))) {
        return {
            family: 'B_VITAMIN',
            unitType: 'mass',
            filterRegex: /\b(b\s*vitamini|vitamin\s*b|b-kompleks|b\s*kompleks|b1\b|b2\b|b3\b|b5\b|b6\b|b7\b|b9\b|b12\b|folat|folik\s*asit|metilfolat|kobalamin|metilkobalamin|adenozilkobalamin|hidroksokobalamin|tiamin|benfotiamin|riboflavin|niasin|niasinamid|nikotinamid|piridoksal|p-5-p|p5p|biyotin|biotin|pantotenik|quatrefolic|5-mthf|mecobalactive)\b/i,
            highlightTerms: [
                'b vitamini', 'b-vitamini', 'vitamin b', 'b kompleksi', 'b-kompleks',
                'b12 vitamini', 'b12', 'b6 vitamini', 'b6', 'b1 vitamini', 'b1',
                'b2 vitamini', 'b2', 'b3 vitamini', 'b3', 'b5 vitamini', 'b5',
                'b7 vitamini', 'b7', 'b9 vitamini', 'b9',
                'metilkobalamin', 'adenozilkobalamin', 'hidroksokobalamin', 'kobalamin',
                'metilfolat', 'folat', 'folik asit', 'folinik asit', 'quatrefolic', '5-mthf',
                'piridoksal-5-fosfat', 'piridoksal', 'p-5-p', 'p5p',
                'benfotiamin', 'tiamin', 'riboflavin', 'niasin', 'niasinamid', 'nikotinamid',
                'biyotin', 'biotin', 'pantotenik asit', 'mecobalactive'
            ],
            sortAliases: ['b-kompleks', 'b12', 'b6', 'folat', 'metilfolat', 'metilkobalamin']
        };
    }

    // 4. C Vitamini Ailesi
    if (/^(c\s*vitamini|vitamin\s*c|c-vitamini|c\s*vit|c)$/i.test(q) ||
        (q.includes('c vitamini') || q.includes('vitamin c') || q.includes('ester-c'))) {
        return {
            family: 'C_VITAMIN',
            unitType: 'mass',
            filterRegex: /\b(c\s*vitamini|vitamin\s*c|c-vitamini|askorbik\s*asit|ascorbic\s*acid|sodyum\s*askorbat|kalsiyum\s*askorbat|ester-c|ester\s*c|lipozomal\s*c)\b/i,
            highlightTerms: [
                'c vitamini', 'c-vitamini', 'vitamin c', 'askorbik asit', 'ascorbic acid',
                'sodyum askorbat', 'kalsiyum askorbat', 'ester-c', 'ester c', 'lipozomal c'
            ],
            sortAliases: ['vitamin c', 'c vitamini', 'askorbik asit', 'ester-c']
        };
    }

    // 5. D3+K2 / K Vitamini
    if (q === 'd3k2' || q === 'd3 k2' || q === 'd3+k2' || q === 'd3/k2' ||
        q === 'k2' || q === 'k vitamini' || q === 'vitamin k' || q === 'k') {
        return {
            family: 'K_VITAMIN',
            unitType: 'mass',
            filterRegex: /\b(d3k2|d3\+k2|d3\s*k2|k2\b|k1\b|mk-7|mk7|menakinon|menaquinone|k\s*vitamini|vitamin\s*k)\b/i,
            highlightTerms: [
                'd3k2', 'd3+k2', 'd3 k2', 'vitamin d3', 'vitamin k2', 'd3', 'k2',
                'mk-7', 'mk7', 'menakinon', 'menaquinone'
            ],
            sortAliases: ['k2', 'mk-7', 'mk7', 'menakinon']
        };
    }

    // 6. Magnezyum
    if (q.includes('magnezyum') || q.includes('magnesium') || q === 'mg') {
        return {
            family: 'MAGNESIUM',
            unitType: 'mass',
            filterRegex: /\b(magnezyum|magnesium|bisglisinat|glisinat|malat|taurat|sitrat|l-treonat|threonate)\b/i,
            highlightTerms: [
                'magnezyum', 'magnesium', 'bisglisinat', 'glisinat', 'malat',
                'taurat', 'sitrat', 'l-treonat', 'threonate'
            ],
            sortAliases: ['magnezyum', 'magnesium', 'bisglisinat', 'malat', 'taurat', 'sitrat', 'l-treonat']
        };
    }

    // 7. Akkermansia
    if (q.includes('akkermansia')) {
        return {
            family: 'AKKERMANSIA',
            unitType: 'mass',
            filterRegex: /\b(akkermansia|akkermansia\s*muciniphila)\b/i,
            highlightTerms: ['akkermansia', 'akkermansia muciniphila'],
            sortAliases: ['akkermansia', 'akkermansia muciniphila']
        };
    }

    // 8. Koenzim Q10 / CoQ10 / Ubikinon / Ubiquinol Ailesi
    if (/^(coq10|coq-10|coq\s*10|koenzim\s*q10|koenzim\s*q-10|koenzim\s*q\s*10|coenzyme\s*q10|coenzyme\s*q-10|ubiquinone|ubikinon|ubiquinol|ubikinol|q10)$/i.test(q) ||
        q.includes('coq10') || q.includes('coq 10') || q.includes('koenzim q10') || q.includes('coenzyme q10') || q.includes('ubikinon') || q.includes('ubiquinone') || q.includes('ubiquinol') || q.includes('ubikinol')) {
        return {
            family: 'COQ10',
            unitType: 'mass',
            filterRegex: /\b(coq10|coq-10|coq\s*10|koenzim\s*q10|koenzim\s*q-10|koenzim\s*q\s*10|coenzyme\s*q10|coenzyme\s*q-10|ubiquinone|ubikinon|ubiquinol|ubikinol|kaneka|ubqh|q-evail|coqnol)\b/i,
            highlightTerms: [
                'koenzim q10', 'koenzim q-10', 'coq10', 'coq-10', 'coenzyme q10', 'coenzyme q-10',
                'ubikinon', 'ubiquinone', 'ubikinol', 'ubiquinol', 'kaneka qh', 'ubqh', 'q-evail', 'coqnol'
            ],
            sortAliases: ['coq10', 'koenzim q10', 'ubiquinol', 'ubikinol', 'ubiquinone', 'ubikinon', 'coenzyme q10']
        };
    }

    return null;
}

// SMART SEARCH HIGHLIGHT FUNCTION (DUAL FIELD SUPPORT)
function highlightMatch(text, query1, query2) {
    if (!text) return '';
    const q1 = (query1 || '').toLowerCase().trim();
    const q2 = (query2 || '').toLowerCase().trim();
    if (!q1 && !q2) return String(text);

    let terms = [];
    [q1, q2].forEach(q => {
        if (!q) return;
        const intent = getClinicalQueryIntent(q);
        if (intent) {
            terms.push(...intent.highlightTerms);
        } else {
            const rawTokens = q.split(/\s+/).filter(t => t.length > 0);
            const meaningfulTokens = rawTokens.filter(t => !['vitamini', 'vitamını', 'vitamin', 'vit'].includes(t));
            const activeTokens = meaningfulTokens.length > 0 ? meaningfulTokens : rawTokens;

            terms.push(q);
            activeTokens.forEach(t => {
                if (t.length > 1 || ['b', 'c', 'd', 'k', 'e', 'a'].includes(t)) {
                    terms.push(t);
                }
            });
            const matchedIng = matchQueryToIngredient(q);
            if (matchedIng) {
                terms.push(matchedIng.name.toLowerCase());
                matchedIng.aliases.forEach(a => terms.push(a.toLowerCase()));
            }
        }
    });

    terms = [...new Set(terms)].filter(t => t.length > 0).sort((a, b) => b.length - a.length);
    if (terms.length === 0) return String(text);

    const escaped = terms.map(t => escapeRegex(t));
    const regexPattern = new RegExp('(' + escaped.map(t => t.length <= 2 ? '\\b' + t + '\\b' : t).join('|') + ')', 'gi');

    return String(text).replace(regexPattern, '<mark class="rx-search-hl">$1</mark>');
}

function isChipSearchMatch(chipText, query1, query2) {
    if (!chipText) return false;
    const q1 = (query1 || '').toLowerCase().trim();
    const q2 = (query2 || '').toLowerCase().trim();
    if (!q1 && !q2) return false;

    const checkOne = (q) => {
        if (!q) return false;
        const t = chipText.toLowerCase();
        const intent = getClinicalQueryIntent(q);
        if (intent) return intent.filterRegex.test(t);

        const rawTokens = q.split(/\s+/).filter(x => x.length > 0);
        const meaningfulTokens = rawTokens.filter(x => !['vitamini', 'vitamını', 'vitamin', 'vit'].includes(x));
        const tokens = meaningfulTokens.length > 0 ? meaningfulTokens : rawTokens;

        return tokens.some(tok => {
            if (tok.length === 1) return new RegExp('\\b' + tok + '\\b', 'i').test(t);
            return t.includes(tok);
        });
    };

    return checkOne(q1) || checkOne(q2);
}

function matchQueryToIngredient(q) {
    const query = q.toLowerCase().trim();
    return CAROUSEL_INGREDIENTS.find(item => {
        if (item.name.toLowerCase() === query || item.label.toLowerCase() === query) return true;
        return item.aliases.some(a => a.toLowerCase() === query);
    }) || null;
}

function parseIngredientChips(icerikText) {
    if (!icerikText) return [];
    let clean = icerikText.replace(/^[0-9]+\s*(Kapsül|Tablet|Şase|Ölçek|Porsiyon|Damla|Flakon)[a-zçğıöşü\s]*:\s*/i, '');
    const parts = clean.split(/[,;•\n]+/).map(p => p.trim()).filter(p => p.length > 0);
    
    return parts.slice(0, 10).map(part => {
        return {
            name: part.split(/\s+[0-9]/)[0].trim(),
            full: part
        };
    });
}

// DOSAGE EXTRACTOR & UNIT NORMALIZER
function extractDosage(product, aliases, unitType = 'mass') {
    const text = ((product.icerik || '') + ' ' + (product.urunAdi || '')).toLowerCase();

    for (const alias of aliases) {
        const aEsc = escapeRegex(alias.toLowerCase());
        
        // IU pattern
        if (unitType === 'iu' || alias.includes('d3') || alias.includes('vitamin d')) {
            const mIU = text.match(new RegExp(aEsc + '[^,\\n;]{0,40}?([0-9.,]+)\\s*(iu|u\\.i\\.|i\\.u\\.|ünite)', 'i'));
            if (mIU) {
                const val = parseFloat(mIU[1].replace(/\./g, '').replace(',', '.'));
                if (!isNaN(val)) {
                    return { standardVal: val, rawStr: val.toLocaleString('tr-TR') + ' IU', unit: 'IU' };
                }
            }
        }

        // Microgram pattern
        const mMcg = text.match(new RegExp(aEsc + '[^,\\n;]{0,40}?([0-9.,]+)\\s*(mcg|µg|ug|mikrogram)', 'i'));
        if (mMcg) {
            const val = parseFloat(mMcg[1].replace(/\./g, '').replace(',', '.'));
            if (!isNaN(val)) {
                const std = (unitType === 'mcg') ? val : (val / 1000);
                return { standardVal: std, rawStr: val + ' µg', unit: 'µg' };
            }
        }

        // Milligram pattern
        const mMg = text.match(new RegExp(aEsc + '[^,\\n;]{0,40}?([0-9.,]+)\\s*mg', 'i'));
        if (mMg) {
            const val = parseFloat(mMg[1].replace(/\./g, '').replace(',', '.'));
            if (!isNaN(val)) {
                const std = (unitType === 'mcg') ? (val * 1000) : val;
                return { standardVal: std, rawStr: val + ' mg', unit: 'mg' };
            }
        }
    }

    return null;
}

// SMART CLINICAL MODULE MATCHER
function isModuleMatch(product, mod) {
    if (!mod || mod === 'HEPSI') return true;
    const m = (product.modul || '').toLowerCase();
    const k = (product.kategori || '').toLowerCase();
    const t = (product.tags || '').toLowerCase();
    const u = (product.urunAdi || '').toLowerCase();
    const i = (product.icerik || '').toLowerCase();
    const combined = m + ' ' + k + ' ' + t + ' ' + u + ' ' + i;

    switch (mod) {
        case 'Bağırsak & Mikrobiyota':
            return combined.includes('bağırsak') || combined.includes('mikrobiyota') || combined.includes('gastrointestinal') || combined.includes('probiyotik') || combined.includes('sibo') || combined.includes('gut') || combined.includes('sindirim') || combined.includes('enzim') || combined.includes('leaky');
        case 'Cilt, Saç & Güzellik':
            return combined.includes('cilt') || combined.includes('saç') || combined.includes('güzellik') || combined.includes('kolajen') || combined.includes('collagen') || combined.includes('keratin') || combined.includes('biotin') || combined.includes('hyaluronik') || combined.includes('skin') || combined.includes('hair') || combined.includes('tırnak');
        case 'Magnezyum & Elektrolit':
            return combined.includes('magnezyum') || combined.includes('elektrolit') || combined.includes('magnesium') || combined.includes('potasyum') || combined.includes('malat') || combined.includes('bisglisinat') || combined.includes('taurat') || combined.includes('sitrat') || combined.includes('treonat');
        case 'Metilasyon & B-Kompleks':
            return combined.includes('metilasyon') || combined.includes('b-kompleks') || combined.includes('folat') || combined.includes('b12') || combined.includes('metilkobalamin') || combined.includes('b vitamini') || combined.includes('homosistein') || combined.includes('p5p') || combined.includes('b6');
        case 'Longevity & Mitokondri':
            return combined.includes('longevity') || combined.includes('mitokondri') || combined.includes('nmn') || combined.includes('resveratrol') || combined.includes('nad') || combined.includes('hücresel') || combined.includes('anti-aging') || combined.includes('coq10') || combined.includes('spermidin') || combined.includes('ubiquinol');
        case 'Metabolizma & Kilo':
            return combined.includes('metabolizma') || combined.includes('kilo') || combined.includes('glukoz') || combined.includes('insülin') || combined.includes('glp-1') || combined.includes('berberin') || combined.includes('metabolik') || combined.includes('yağ yak') || combined.includes('krom');
        case 'Kadın Sağlığı & Hormon':
            return combined.includes('kadın') || combined.includes('hormon') || combined.includes('menopoz') || combined.includes('pcos') || combined.includes('tiroid') || combined.includes('östrojen') || combined.includes('progesteron') || combined.includes('inositol') || combined.includes('pms');
        case 'Nöroloji, Stres & Uyku':
            return combined.includes('nöroloji') || combined.includes('stres') || combined.includes('uyku') || combined.includes('bilişsel') || combined.includes('odak') || combined.includes('anksiyete') || combined.includes('melatonin') || combined.includes('gaba') || combined.includes('ashwagandha') || combined.includes('teanin');
        case 'Bağışıklık & Esansiyel':
            return combined.includes('bağışıklık') || combined.includes('immün') || combined.includes('esansiyel') || combined.includes('c vitamini') || combined.includes('çinko') || combined.includes('d3') || combined.includes('vitamin d') || combined.includes('mürver') || combined.includes('propolis') || combined.includes('quercetin');
        default:
            return m.includes(mod.toLowerCase());
    }
}

// PRECISION FILTER AND SORT (EN YÜKSEKTEN EN DÜŞÜĞE DOĞRU OTOMATİK SIRALAMA)
function filterAndSortProducts() {
    initProductSearchIndex();
    let list = [...ALL_PRODUCTS];

    // 1. Origin filter (TR vs ABD)
    if (currentOrigin !== 'ALL') {
        list = list.filter(p => p.mensei === currentOrigin);
    }

    // 2. Module filter (Smart clinical match)
    if (currentModule !== 'HEPSI') {
        list = list.filter(p => isModuleMatch(p, currentModule));
    }

    // 3. Search query filter (Dual Slot & Exclusion Engine)
    let targetSortAliases = null;
    let targetSortLabel = '';
    let targetUnitType = 'mass';

    const q1 = (searchQuery1 || '').toLowerCase().trim();
    const q2 = (searchQuery2 || '').toLowerCase().trim();
    const qEx = (searchExclude || '').toLowerCase().trim();

    if (q1 || q2 || qEx) {
        const intent1 = q1 ? getClinicalQueryIntent(q1) : null;
        const intent2 = q2 ? getClinicalQueryIntent(q2) : null;
        const primaryIntent = intent1 || intent2;

        function checkTermMatch(p, query, intent) {
            if (!query) return true;
            const titleAndIcerik = ((p.urunAdi || '') + ' ' + (p.icerik || '')).toLowerCase();
            const fullText = (titleAndIcerik + ' ' + (p.marka || '') + ' ' + (p.tags || '') + ' ' + (p.endikasyon || '')).toLowerCase();

            if (intent) {
                if (!intent.filterRegex.test(fullText)) return false;

                const aliases = intent.sortAliases || intent.highlightTerms;
                const negPattern = '\\b(' + aliases.map(escapeRegex).join('|') + ')\\b[^.!?\\n]{0,30}?(içermez|bulunmaz|yoktur|free|minus)';
                if (new RegExp(negPattern, 'i').test(titleAndIcerik)) return false;

                const emilimPattern = '\\b(' + aliases.map(escapeRegex).join('|') + ')\\b\\s+(emilimi|emilimini|emilim|desteği)';
                if (new RegExp(emilimPattern, 'i').test(titleAndIcerik)) {
                    const dos = extractDosage(p, aliases, intent.unitType);
                    if (!dos) return false;
                }
                return true;
            }

            const rawTokens = query.split(/\s+/).filter(t => t.length > 0);
            const meaningfulTokens = rawTokens.filter(t => !['vitamini', 'vitamını', 'vitamin', 'vit'].includes(t));
            const tokens = meaningfulTokens.length > 0 ? meaningfulTokens : rawTokens;

            for (let tok of tokens) {
                if (tok.length >= 2) {
                    const negRe = new RegExp('\\b' + escapeRegex(tok) + '\\b[^.!?\\n]{0,25}?(içermez|bulunmaz|yoktur|free)', 'i');
                    if (negRe.test(titleAndIcerik)) return false;
                }
            }

            return tokens.every(token => {
                if (token.length === 1) {
                    return new RegExp('\\b' + token + '\\b', 'i').test(fullText);
                }
                return fullText.includes(token);
            });
        }

        list = list.filter(p => {
            if (!checkTermMatch(p, q1, intent1)) return false;
            if (!checkTermMatch(p, q2, intent2)) return false;

            if (qEx) {
                const fullText = ((p.urunAdi || '') + ' ' + (p.icerik || '') + ' ' + (p.marka || '') + ' ' + (p.tags || '')).toLowerCase();
                if (fullText.includes(qEx)) return false;
            }
            return true;
        });

        if (primaryIntent) {
            targetSortAliases = primaryIntent.sortAliases || primaryIntent.highlightTerms;
            targetSortLabel = primaryIntent.family;
            targetUnitType = primaryIntent.unitType || 'mass';
        } else {
            const rawTokens = [...q1.split(/\s+/), ...q2.split(/\s+/)].filter(t => t.length > 0);
            const matchedIng = (q1 && matchQueryToIngredient(q1)) || (q2 && matchQueryToIngredient(q2));
            if (matchedIng) {
                targetSortAliases = matchedIng.aliases;
                targetSortLabel = matchedIng.label;
            } else {
                targetSortAliases = rawTokens;
                targetSortLabel = [q1, q2].filter(Boolean).join(' + ');
            }
        }
    } else if (activeRankingIngredient) {
        const aliases = activeRankingIngredient.aliases;
        list = list.filter(p => {
            const full = ((p.urunAdi || '') + ' ' + (p.icerik || '') + ' ' + (p.tags || '')).toLowerCase();
            return aliases.some(a => full.includes(a));
        });
        targetSortAliases = aliases;
        targetSortLabel = activeRankingIngredient.label;
    }

    // 4. Sort automatically: Purity Tier (Saf/Tekil En Üstte) -> Dozaj Azalan -> Karışıklar En Altta
    if (targetSortAliases && targetSortAliases.length > 0) {
        list.forEach(p => {
            p._purityTier = getPurityTier(p, searchQuery, targetSortAliases);
            p._active_dosage = extractDosage(p, targetSortAliases, targetUnitType);
        });

        list.sort((a, b) => {
            // 1. Purity Tier: Tier 1 (Saf/Tekil) en üstte, Tier 2 (Sinerji) ortada, Tier 3 (Karışık/Kompleks) en altta
            const tierA = a._purityTier || 3;
            const tierB = b._purityTier || 3;
            if (tierA !== tierB) {
                return tierA - tierB;
            }

            // 2. Aynı tier içinde en yüksek dozajdan en düşüğe otomatik sıralama
            const da = a._active_dosage ? a._active_dosage.standardVal : 0;
            const db = b._active_dosage ? b._active_dosage.standardVal : 0;
            if (db !== da) {
                return db - da;
            }

            // 3. Eşit dozlarda başlık doğrudan eşleşmesi önceliği
            const titleA = (a.urunAdi || '').toLowerCase();
            const titleB = (b.urunAdi || '').toLowerCase();
            const matchA = targetSortAliases.some(x => titleA.includes(x.toLowerCase()));
            const matchB = targetSortAliases.some(x => titleB.includes(x.toLowerCase()));
            if (matchA && !matchB) return -1;
            if (!matchA && matchB) return 1;

            return (a.urunAdi || '').localeCompare(b.urunAdi || '', 'tr');
        });

        const indicator = document.getElementById('activeSortIndicator');
        if (indicator) {
            let label = targetSortLabel || [q1, q2].filter(Boolean).join(' + ') || searchQuery;
            if (label === 'COQ10') label = 'Koenzim Q10 / CoQ10 / Ubiquinol';
            if (label === 'D_VITAMIN') label = 'D Vitamini Ailesi';
            if (label === 'B12_VITAMIN') label = 'B12 Vitamini (Aktif Metilkobalamin)';
            if (label === 'MAGNESIUM') label = 'Magnezyum Formülasyonları';
            if (label === 'AKKERMANSIA') label = 'Akkermansia Muciniphila';

            let extraInfo = '';
            if (q1 && q2) extraInfo = ' (1. Kelime: "' + q1 + '" + 2. Kelime: "' + q2 + '")';
            if (qEx) extraInfo += ' [Dışlanan: "' + qEx + '"]';

            indicator.innerHTML = '⚡ Akıllı Klinik Arama: <strong>' + label + extraInfo + '</strong> &mdash; <span style="color:#059669; font-weight:700;">✨ Saf / Tekil Formüller En Üstte</span> &rarr; <span style="color:#2563eb; font-weight:600;">⚡ Sinerjik Formüller</span> &rarr; <span style="color:#6b7280;">🌿 Kompleks Karışımlar</span> (Dozaj Azalan)';
        }
    } else {
        list.forEach(p => {
            delete p._purityTier;
            delete p._active_dosage;
        });
        const indicator = document.getElementById('activeSortIndicator');
        if (indicator) indicator.textContent = 'Sıralama: Standart Klinik Katalog';
    }

    return list;
}

// RENDER ALL (HIGH PERFORMANCE)
const PAGE_CHUNK = 40;
let currentRenderLimit = PAGE_CHUNK;

function loadMoreProducts() {
    currentRenderLimit += PAGE_CHUNK;
    renderAll(true);
}

function renderAll(isIncremental = false) {
    if (!isIncremental) {
        currentRenderLimit = PAGE_CHUNK;
    }
    const filtered = filterAndSortProducts();
    
    const countEl = document.getElementById('resultsCount');
    if (countEl) {
        countEl.innerHTML = 'Gösterilen: <strong>' + Math.min(currentRenderLimit, filtered.length).toLocaleString('tr-TR') + ' / ' + filtered.length.toLocaleString('tr-TR') + '</strong> takviye';
    }

    if (currentViewMode === 'table') {
        renderProductsTable(filtered, isIncremental);
    } else {
        renderProductsGrid(filtered, isIncremental);
    }
    updateViewModeUI();
}

function updateOriginBadges() {
    const elAll = document.getElementById('badgeOriginAll');
    const elTr = document.getElementById('badgeOriginTr');
    const elAbd = document.getElementById('badgeOriginAbd');
    if (elAll) elAll.textContent = ALL_PRODUCTS.length.toLocaleString('tr-TR');
    if (elTr) elTr.textContent = ALL_PRODUCTS.filter(p => p.mensei === 'TR').length.toLocaleString('tr-TR');
    if (elAbd) elAbd.textContent = ALL_PRODUCTS.filter(p => p.mensei === 'ABD').length.toLocaleString('tr-TR');
}

function renderCarouselTrack() {
    const track = document.getElementById('carouselTrack');
    if (!track) return;

    let html = '';
    CAROUSEL_INGREDIENTS.forEach(item => {
        const isSelected = (activeRankingIngredient && activeRankingIngredient.name === item.name) ||
                           (searchQuery.toLowerCase().trim() === item.name.toLowerCase());
        const activeClass = isSelected ? 'active' : '';

        html += `
            <button class="carousel-pill-btn ${activeClass}" onclick="selectCarouselIngredient('${item.name}')">
                <span class="pill-dot">⚡</span>
                <span>${item.label}</span>
            </button>
        `;
    });
    track.innerHTML = html;
}

function selectCarouselIngredient(name) {
    const item = CAROUSEL_INGREDIENTS.find(x => x.name.toLowerCase() === name.toLowerCase() || x.label.toLowerCase() === name.toLowerCase());
    if (!item) return;

    if (activeRankingIngredient && activeRankingIngredient.name === item.name) {
        clearActiveRanking();
        return;
    }

    activeRankingIngredient = item;
    searchQuery1 = item.name;
    searchQuery2 = '';
    searchQuery = item.name;
    const input1 = document.getElementById('mainSearchInput');
    if (input1) input1.value = item.name;
    const input2 = document.getElementById('secondSearchInput');
    if (input2) input2.value = '';
    updateClearButtons();

    currentModule = 'HEPSI';
    document.querySelectorAll('.module-tab').forEach(b => {
        b.classList.toggle('active', b.dataset.module === 'HEPSI');
    });

    saveRecentSearch(item.name);
    renderAll();
}

function scrollCarousel(distance) {
    const track = document.getElementById('carouselTrack');
    if (track) {
        track.scrollBy({ left: distance, behavior: 'smooth' });
    }
}

function renderRankingBanner() {
    const banner = document.getElementById('rankingBanner');
    if (!banner) return;

    if (activeRankingIngredient) {
        banner.style.display = 'flex';
        document.getElementById('rankingBannerTitle').textContent = 
            '⭐ ' + activeRankingIngredient.label + ' İçeriğine Göre En Yüksek Dozajdan Düşüğe Sıralandı';
    } else {
        banner.style.display = 'none';
    }
}

function clearActiveRanking() {
    activeRankingIngredient = null;
    searchQuery1 = '';
    searchQuery2 = '';
    searchExclude = '';
    searchQuery = '';
    const input1 = document.getElementById('mainSearchInput');
    if (input1) input1.value = '';
    const input2 = document.getElementById('secondSearchInput');
    if (input2) input2.value = '';
    const inputEx = document.getElementById('excludeSearchInput');
    if (inputEx) inputEx.value = '';
    updateClearButtons();
    currentRenderLimit = PAGE_CHUNK;
    renderAll();
}

// RECENTLY VIEWED & RECENT SEARCHES
function getRecentlyViewed() {
    try {
        const raw = localStorage.getItem('lara_recently_viewed');
        return raw ? JSON.parse(raw) : [];
    } catch(e) {
        return [];
    }
}

function saveRecentlyViewed(id) {
    try {
        let list = getRecentlyViewed();
        list = list.filter(x => x !== id);
        list.unshift(id);
        list = list.slice(0, 8);
        localStorage.setItem('lara_recently_viewed', JSON.stringify(list));
    } catch(e) {}
}

function clearRecentlyViewed() {
    try {
        localStorage.removeItem('lara_recently_viewed');
        renderRecentlyViewedSection();
    } catch(e) {}
}

function renderRecentlyViewedSection() {
    const container = document.getElementById('recentlyViewedItems');
    const section = document.getElementById('recentlyViewedSection');
    if (!container || !section) return;

    const ids = getRecentlyViewed();
    if (ids.length === 0) {
        section.style.display = 'none';
        return;
    }

    section.style.display = 'block';
    let html = '';
    ids.forEach(id => {
        const p = ALL_PRODUCTS.find(x => x.id === id);
        if (p) {
            html += `
                <div class="recent-item-pill" onclick="openDetailModal(${p.id})">
                    <span>💊</span>
                    <span>${p.urunAdi}</span>
                </div>
            `;
        }
    });
    container.innerHTML = html;
}

function saveRecentSearch(q) {
    try {
        if (!q || !q.trim()) return;
        let searches = JSON.parse(localStorage.getItem('lara_recent_searches') || '[]');
        searches = searches.filter(x => x.toLowerCase() !== q.toLowerCase());
        searches.unshift(q.trim());
        localStorage.setItem('lara_recent_searches', JSON.stringify(searches.slice(0, 10)));
    } catch(e) {}
}

