function onChipClick(chipText, event) {
    if (event) event.stopPropagation();
    const cleanName = chipText.split(/\s+[0-9]/)[0].trim();
    
    const input1 = document.getElementById('mainSearchInput');
    const input2 = document.getElementById('secondSearchInput');

    if (!searchQuery1) {
        searchQuery1 = cleanName;
        if (input1) input1.value = cleanName;
    } else if (!searchQuery2 && searchQuery1.toLowerCase() !== cleanName.toLowerCase()) {
        searchQuery2 = cleanName;
        if (input2) input2.value = cleanName;
    } else {
        searchQuery1 = cleanName;
        if (input1) input1.value = cleanName;
        searchQuery2 = '';
        if (input2) input2.value = '';
    }

    searchQuery = [searchQuery1, searchQuery2].filter(Boolean).join(' ');
    updateClearButtons();
    currentRenderLimit = PAGE_CHUNK;
    renderAll();
    window.scrollTo({ top: 320, behavior: 'smooth' });
}

function openDetailModal(id) {
    const p = ALL_PRODUCTS.find(x => x.id === id);
    if (!p) return;
    activeModalProduct = p;
    saveRecentlyViewed(p.id);

    document.getElementById('modalBrand').textContent = p.marka || 'LARAHEALTH';
    document.getElementById('modalTitle').innerHTML = highlightMatch(p.urunAdi, searchQuery);

    const mb = document.getElementById('modalMenseiBadge');
    mb.className = p.mensei === 'TR' ? 'badge-mensei badge-mensei-tr' : 'badge-mensei badge-mensei-abd';
    mb.textContent = p.mensei === 'TR' ? '🇹🇷 Türkiye Eczane & Yerli' : '🇺🇸 ABD / İthal Fonksiyonel';

    const fullIcerikEl = document.getElementById('modalIcerikFull');
    if (fullIcerikEl) {
        fullIcerikEl.innerHTML = highlightMatch(p.icerik || 'Klinik formülasyon bilgisi bulunmamaktadır.', searchQuery);
    }

    document.getElementById('modalEndikasyon').innerHTML = highlightMatch(p.endikasyon || 'Detaylı klinik açıklama girilmemiş.', searchQuery);
    document.getElementById('modalDozaj').textContent = p.dozaj || 'Hekim / diyetisyen önerisine göre kullanılır.';
    document.getElementById('modalKontrendikasyon').textContent = p.kontrendikasyon || 'Bilinen kontrendikasyon bulunmamaktadır.';
    document.getElementById('modalEtkilesim').textContent = p.etkilesim || 'Bilinen ilaç etkileşimi bulunmamaktadır.';

    const siteRow = document.getElementById('modalWebSitesiRow');
    const siteA = document.getElementById('modalWebSitesi');
    if (p.webSitesi && p.webSitesi.startsWith('http')) {
        siteA.href = p.webSitesi;
        siteRow.style.display = 'block';
    } else {
        siteRow.style.display = 'none';
    }

    const chips = parseIngredientChips(p.icerik);
    let chipsHtml = '';
    chips.forEach(c => {
        chipsHtml += `
            <span class="ing-chip-item highlighted">
                ⚡ ${highlightMatch(c.full, searchQuery)}
            </span>
        `;
    });
    document.getElementById('modalIngredientChips').innerHTML = chipsHtml;

    const productImgCard = document.getElementById('modalProductImgCard');
    const productImg = document.getElementById('modalProductImg');
    const modalImg = document.getElementById('modalProspektusImg');
    const modalSection = document.getElementById('modalProspektusSection');

    const hasProsp = !!p.prospektus_gorsel;
    const isGorselProsp = p.gorsel && (p.gorsel.toLowerCase().includes('prospektus') || p.gorsel.toLowerCase().includes('besin_deger'));

    // 1. Resmi Prospektus / Besin Degerleri Gorseli
    if (hasProsp) {
        if (modalImg) modalImg.src = p.prospektus_gorsel;
        if (modalSection) modalSection.style.display = 'block';
    } else if (isGorselProsp) {
        if (modalImg) modalImg.src = p.gorsel;
        if (modalSection) modalSection.style.display = 'block';
    } else {
        if (modalSection) modalSection.style.display = 'none';
        if (modalImg) modalImg.src = '';
    }

    // 2. Urun Orijinal Ambalaj Gorseli (Sise / Kutu)
    const bottleSrc = p.ambalaj_gorsel || (p.gorsel && !p.gorsel.toLowerCase().includes('prospektus') ? p.gorsel : null);
    if (bottleSrc) {
        if (productImg) productImg.src = bottleSrc;
        if (productImgCard) productImgCard.style.display = 'block';
    } else {
        if (productImgCard) productImgCard.style.display = 'none';
        if (productImg) productImg.src = '';
    }

    const isInRx = prescriptionList.some(r => r.id === p.id);
    const modalBtn = document.getElementById('modalBtnAddRx');
    if (modalBtn) {
        modalBtn.textContent = isInRx ? '✓ Protokolden Çıkar' : '+ Reçete Protokolüne Ekle';
    }

    document.getElementById('detailModalOverlay').style.display = 'flex';
}

function closeDetailModal(e) {
    if (e && e.target !== document.getElementById('detailModalOverlay') && !e.target.classList.contains('close-btn')) return;
    document.getElementById('detailModalOverlay').style.display = 'none';
    activeModalProduct = null;
    renderRecentlyViewedSection();
}

function addModalProductToRx() {
    if (!activeModalProduct) return;
    togglePrescriptionItem(activeModalProduct.id);
    const isInRx = prescriptionList.some(r => r.id === activeModalProduct.id);
    const modalBtn = document.getElementById('modalBtnAddRx');
    if (modalBtn) {
        modalBtn.textContent = isInRx ? '✓ Protokolden Çıkar' : '+ Reçete Protokolüne Ekle';
    }
}

// ==========================================================================
// TAKVİYE KULLANIM PLANI & WORD EXPORT ENGINE (TAM KLİNİK MODÜL)
// ==========================================================================
function parseSupplementUsage(p) {
    const dozaj = (p.dozaj || '').trim();
    let doz = '1 x 1 kapsül';
    let siklik = 'Günde 1 kez';
    let zaman = 'Sabah';
    let kullanim = 'Yemekten sonra';
    let sure = '3 ay';
    let not = '';

    const dLower = dozaj.toLowerCase();

    // Doz
    if (dLower.includes('2x2') || dLower.includes('2 x 2')) {
        doz = '2 x 2 kapsül';
        siklik = 'Günde 2 kez';
    } else if (dLower.includes('2 kapsül') || dLower.includes('2 tablet')) {
        doz = '1 x 2 kapsül';
    } else if (dLower.includes('1-2 kapsül') || dLower.includes('1-2 tablet')) {
        doz = '1 x 1-2 kapsül';
    } else if (dLower.includes('saşe') || dLower.includes('sase')) {
        doz = '1 x 1 saşe';
    } else if (dLower.includes('ölçek') || dLower.includes('olcek')) {
        doz = '1 x 1 ölçek';
    } else if (dLower.includes('damla')) {
        const m = dLower.match(/(\d+)\s*damla/);
        doz = m ? (m[1] + ' damla') : '10 damla';
    } else if (dLower.includes('flakon')) {
        doz = '1 flakon';
    } else if (dLower.includes('pastil')) {
        doz = '1 x 1 pastil';
    }

    // Sıklık
    if (dLower.includes('günde 2') || dLower.includes('2x') || dLower.includes('sabah akşam')) {
        siklik = 'Günde 2 kez';
    } else if (dLower.includes('günde 3') || dLower.includes('3x')) {
        siklik = 'Günde 3 kez';
    } else if (dLower.includes('gün aşırı') || dLower.includes('haftada')) {
        siklik = 'Gün aşırı';
    }

    // Zaman
    if (dLower.includes('yatmadan') || dLower.includes('gece') || dLower.includes('uyku')) {
        zaman = 'Yatmadan';
    } else if (dLower.includes('akşam') || dLower.includes('aksam')) {
        zaman = 'Akşam';
    } else if (dLower.includes('öğle') || dLower.includes('ogle')) {
        zaman = 'Öğle';
    } else {
        zaman = 'Sabah';
    }

    // Kullanım
    if (dLower.includes('aç') || dLower.includes('ac karnina')) {
        kullanim = 'Aç karnına';
    } else if (dLower.includes('önce') || dLower.includes('oncesi')) {
        kullanim = 'Yemekten önce';
    } else if (dLower.includes('birlikte') || dLower.includes('yemekle')) {
        kullanim = 'Yemekle birlikte';
    } else {
        kullanim = 'Yemekten sonra';
    }

    return { doz, siklik, zaman, kullanim, sure, not };
}

function togglePrescriptionItem(id) {
    const existingIdx = prescriptionList.findIndex(r => r.id === id);
    if (existingIdx >= 0) {
        prescriptionList.splice(existingIdx, 1);
    } else {
        const p = ALL_PRODUCTS.find(x => x.id === id);
        if (p) {
            const parsed = parseSupplementUsage(p);
            prescriptionList.push({
                id: p.id,
                urunAdi: p.urunAdi,
                marka: p.marka || 'LaraHealth',
                doz: parsed.doz,
                siklik: parsed.siklik,
                zaman: parsed.zaman,
                kullanim: parsed.kullanim,
                sure: parsed.sure,
                not: parsed.not
            });
        }
    }
    updateRxUI();
    renderAll();
}

function updateRxUI() {
    const countEl = document.getElementById('headerRxCount');
    if (countEl) countEl.textContent = prescriptionList.length;
    renderRxDrawerBody();
}

function toggleRxDrawer() {
    const drawer = document.getElementById('rxDrawer');
    const overlay = document.getElementById('rxDrawerOverlay');
    if (!drawer || !overlay) return;
    if (drawer.classList.contains('open')) {
        drawer.classList.remove('open');
        overlay.classList.remove('open');
    } else {
        drawer.classList.add('open');
        overlay.classList.add('open');
        renderRxDrawerBody();
    }
}

