let rxToastMessage = '';

function getCustomProtocols() {
    try {
        const stored = localStorage.getItem('lara_clinical_protocols');
        return stored ? JSON.parse(stored) : [];
    } catch(e) {
        return [];
    }
}

function saveCustomProtocolsToStorage(list) {
    try {
        localStorage.setItem('lara_clinical_protocols', JSON.stringify(list));
    } catch(e) {
        console.error('Protocols storage error:', e);
    }
}

function getAllProtocols() {
    const custom = getCustomProtocols();
    return [...DEFAULT_CLINICAL_PROTOCOLS, ...custom];
}

function applyClinicalProtocol(protocolId) {
    const all = getAllProtocols();
    const proto = all.find(p => p.id === protocolId);
    if (!proto) return;

    proto.supplements.forEach(sup => {
        const exists = prescriptionList.some(r => r.urunAdi === sup.urunAdi);
        if (!exists) {
            prescriptionList.push({
                id: sup.productId || Date.now() + Math.random(),
                urunAdi: sup.urunAdi,
                marka: sup.marka || '',
                doz: sup.doz || '1 x 1 kapsül',
                siklik: sup.siklik || 'Günde 1 kez',
                zaman: sup.zaman || 'Sabah',
                kullanim: sup.kullanim || 'Yemekten sonra',
                sure: sup.sure || '3 ay',
                not: sup.not || ''
            });
        }
    });

    rxToastMessage = '✓ "' + proto.name + '" takviye planına aktarıldı (' + proto.supplements.length + ' ürün eklendi).';
    updateRxUI();
    renderAll();

    setTimeout(() => {
        rxToastMessage = '';
        const toastEl = document.getElementById('rxToastBanner');
        if (toastEl) toastEl.style.display = 'none';
    }, 4500);
}

function saveCurrentRxAsProtocol() {
    if (prescriptionList.length === 0) {
        alert('Protokol olarak kaydetmek için önce plana en az bir takviye ekleyiniz.');
        return;
    }

    const name = prompt('Hazır Protokol Adı Giriniz (örn: 6 Haftalık SIBO Destek Protokolü):', 'Özel Klinik Protokol');
    if (!name || !name.trim()) return;

    const category = prompt('Protokol Kategorisi (örn: Bağırsak & Sindirim, Kilo Kontrolü, vb.):', 'Kişiye Özel Protokol') || 'Kişiye Özel Protokol';
    const duration = prompt('Tahmini Tedavi Süresi (örn: 4 Hafta, 3 Ay):', '3 Ay') || '3 Ay';

    const newProto = {
        id: 'custom-' + Date.now(),
        isCustom: true,
        name: name.trim(),
        category: category.trim(),
        duration: duration.trim(),
        badge: 'Diyetisyen Özel Protokolü',
        description: 'Diyetisyen Betül Çetin tarafından kaydedilmiş özel klinik tedavi ve takviye planı.',
        supplements: prescriptionList.map(item => ({
            productId: item.id,
            urunAdi: item.urunAdi,
            marka: item.marka,
            doz: item.doz || '1 x 1 kapsül',
            siklik: item.siklik || 'Günde 1 kez',
            zaman: item.zaman || 'Sabah',
            kullanim: item.kullanim || 'Yemekten sonra',
            sure: item.sure || '3 ay',
            not: item.not || ''
        }))
    };

    const customs = getCustomProtocols();
    customs.unshift(newProto);
    saveCustomProtocolsToStorage(customs);

    rxToastMessage = '✓ "' + newProto.name + '" başarıyla hazır protokoller arasına kaydedildi.';
    renderRxDrawerBody();

    setTimeout(() => {
        rxToastMessage = '';
        const toastEl = document.getElementById('rxToastBanner');
        if (toastEl) toastEl.style.display = 'none';
    }, 4500);
}

function deleteCustomProtocol(protocolId) {
    if (!confirm('Bu özel hazır protokolü silmek istediğinize emin misiniz?')) return;
    let customs = getCustomProtocols();
    customs = customs.filter(p => p.id !== protocolId);
    saveCustomProtocolsToStorage(customs);
    renderRxDrawerBody();
}

function renderReadyProtocolsHtml() {
    const allProtocols = getAllProtocols();

    let toastHtml = '';
    if (rxToastMessage) {
        toastHtml = `
            <div class="rx-toast-banner" id="rxToastBanner">
                <span>${rxToastMessage}</span>
                <span style="cursor:pointer; margin-left: 12px; font-weight: bold;" onclick="this.parentElement.style.display='none'">✕</span>
            </div>
        `;
    }

    let cardsHtml = '';
    allProtocols.forEach(proto => {
        let itemsListHtml = '';
        proto.supplements.forEach(sup => {
            const extraNote = sup.not ? ` · <span style="color: #869FA8; font-weight: 600;">${sup.not}</span>` : '';
            itemsListHtml += `
                <div class="protocol-item-row">
                    <span class="protocol-item-name">💊 <strong>${sup.urunAdi}</strong> <small style="color:#64748B;">(${sup.marka})</small>${extraNote}</span>
                    <span class="protocol-item-meta">${sup.doz} · ${sup.zaman} · ${sup.kullanim}</span>
                </div>
            `;
        });

        cardsHtml += `
            <div class="protocol-card">
                <div class="protocol-card-header">
                    <div>
                        <div class="protocol-card-name">${proto.name}</div>
                        <div style="font-size: 11px; color: #869FA8; font-weight: 600; margin-top: 2px;">${proto.badge || ''}</div>
                    </div>
                    <div class="protocol-card-badges">
                        <span class="protocol-badge-duration">⏱️ ${proto.duration}</span>
                        <span class="protocol-badge-category">${proto.category}</span>
                    </div>
                </div>
                <div class="protocol-card-desc">${proto.description}</div>
                <div class="protocol-items-preview">
                    <div style="font-size: 11px; font-weight: 700; color: #475569; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.4px;">
                        İÇERİĞİNDEKİ TAKVİYELER VE KULLANIM PLANI (${proto.supplements.length} Ürün):
                    </div>
                    ${itemsListHtml}
                </div>
                <div class="protocol-card-actions">
                    <button class="btn-protocol-load" onclick="applyClinicalProtocol('${proto.id}')">
                        📥 Bu Protokolü Plana Aktar
                    </button>
                    ${proto.isCustom ? `
                        <button class="btn-protocol-delete" onclick="deleteCustomProtocol('${proto.id}')" title="Bu özel şablonu sil">
                            🗑️ Sil
                        </button>
                    ` : ''}
                </div>
            </div>
        `;
    });

    return `
        <div class="rx-protocols-section">
            ${toastHtml}
            <div class="rx-protocols-header">
                <div>
                    <div class="rx-protocols-title">📋 Hazır Klinik Reçeteler & Tedavi Protokolleri</div>
                    <div class="rx-protocols-subtitle">
                        Uzman diyetisyen hazır protokolleri. Tek tıkla plana aktarabilir veya hastanıza göre reçeteyi özelleştirebilirsiniz.
                    </div>
                </div>
                <button class="btn-save-as-protocol" onclick="saveCurrentRxAsProtocol()" title="Mevcut plandaki takviyeleri yeni bir hazır protokol olarak kaydet">
                    💾 Mevcut Protokolü Kaydet
                </button>
            </div>
            <div class="rx-protocols-list">
                ${cardsHtml}
            </div>
        </div>
    `;
}

