function copyPrescriptionText() {
    if (prescriptionList.length === 0) {
        alert('Kopyalanacak takviye bulunamadı.');
        return;
    }

    const danisan = (rxMetadata.kime || 'Belirtilmedi').trim();
    const tarih = rxMetadata.tarih || new Date().toLocaleDateString('tr-TR');
    const kontrol = rxMetadata.kontrol || calculateDefaultControlDate();

    let txt = '=================================================\\n';
    txt += 'TAKVİYE KULLANIM PROTOKOLÜ • LARAHEALTH KLİNİK\\n';
    txt += 'Danışan: ' + danisan + ' | Tarih: ' + tarih + ' | Kontrol: ' + kontrol + '\\n';
    txt += 'Uzman: Diyetisyen Betül Çetin\\n';
    txt += '=================================================\\n\\n';

    prescriptionList.forEach((it, idx) => {
        txt += (idx + 1) + '. ' + it.urunAdi + ' (' + it.marka + ')\\n';
        txt += '   Doz: ' + (it.doz || '-') + ' | Sıklık: ' + (it.siklik || '-') + ' | Zaman: ' + (it.zaman || '-') + ' | Kullanım: ' + (it.kullanim || '-') + ' | Süre: ' + (it.sure || '-') + '\\n';
        if (it.not) txt += '   Not: ' + it.not + '\\n';
        txt += '\\n';
    });

    txt += '-------------------------------------------------\\n';
    txt += 'Not: Bu protokol kişiye özeldir. İlaç ve takviyeleri hekim ve diyetisyeninize danışmadan kafanıza göre almayınız ve kullanmayınız; doz veya kullanım sürelerini değiştirmeyiniz.\\n';

    navigator.clipboard.writeText(txt).then(() => {
        alert('Takviye kullanım protokolü metin formatında panoya kopyalandı.');
    }).catch(() => {
        alert('Panoya kopyalama başarısız oldu.');
    });
}

// INITIALIZATION
function initApp() {
    renderAll();
    updateRxUI();
}
